      setLoadingUserInfo(true);

      try {
        const info = await getUserInfo();

        if (!isCancelled) {
          setUserInfo((info ?? null) as UserInfo | null);
        }
      } catch {
        if (!isCancelled) {
          setContactError('Connected, but Particle did not return user info yet.');
        }
      } finally {
        if (!isCancelled) {
          setLoadingUserInfo(false);
        }
      }
    };

    void fetchUserInfo();

    return () => {
      isCancelled = true;
    };
  }, [getUserInfo, isConnected, isParticleAuth]);

